private AdmissionTx runAdmissionTx(IdempotencyHandle handle, PrincipalContext principal,
        M4A03Metadata meta, CarePlanRow plan, UUID microcrystalId, UUID mediaId,
        Long providedRevision) {
    return txTemplate.execute(status -> {
        if (principal.principalType() == PrincipalType.GIMBAL) {
            GimbalPointer p = gimbalRepository.lockById(principal.gimbalUuid()).orElseThrow(this::taskReplaced);
            if (p.currentAssessmentId()==null || !p.currentAssessmentId().equals(meta.currentTaskId())
                    || p.currentAssessmentRevision() != providedRevision) throw taskReplaced();
        }
        MicrocrystalRow mic = microcrystalRepository.lockById(microcrystalId)
                .orElseThrow(() -> authorization.notVisible());
        CarePlanRow locked = planRepository.lockById(plan.id())
                .orElseThrow(() -> authorization.notVisible());
        if (!"ready".equals(locked.generationStatus())) throw planNotReady(null);
        if (locked.completedCount() >= locked.targetCount()) throw planCompleted();
        requireCapabilityCovered(locked, mic);
        UUID executionId = UUID.randomUUID();
        Instant now = Instant.now();
        String planSnapshot = buildPlanSnapshot(locked, microcrystalId? no, mediaId, meta, now);
        String latestVerification = buildLatestVerification(mediaId, meta, now);
        careExecutionRepository.insert(new NewExecution(...));
        if (principal.principalType()==APP) {
            if (!accessRepository.hasActiveGrantForUpdate(principal.accountUuid(), locked.memberId()))
                throw authorization.notVisible();
        }
        updateMediaOwnership(mediaId, executionId, locked.memberId());
        idempotencyService.completeSuccess(handle, "care_execution", executionId, resultSummary);
        return new AdmissionTx(executionId, locked, now, mediaId);
    });
}
