private VerificationDto verificationProjection(String rawLatest, String revision, Instant fallbackVerifiedAt, String fallbackPurpose, boolean replayed) {
   JsonNode node = readJsonObject(rawLatest);
   String captureId=null, continuityId=null, purpose=null; Instant verifiedAt=null;
   if (node != null) {
      captureId = textOrNull(node, "capture_id", "captureId");
      continuityId = textOrNull(node, "client_continuity_id", "clientContinuityId");
      purpose = textOrNull(node, "applicable_purpose", "applicablePurpose");
      String v = textOrNull(node, "verified_at", "verifiedAt");
      if (v != null) { try { verifiedAt = Instant.parse(v); } catch (DateTimeParseException ignored) {} }
   }
   if (verifiedAt == null) verifiedAt = fallbackVerifiedAt;
   if (purpose == null) purpose = fallbackPurpose;
   return new VerificationDto(revision, captureId, continuityId, rfc3339(verifiedAt), null, purpose, replayed);
}
