private static String stateMachineStatus(CareExecutionRow exec, ExecutionObservationDto obs, boolean newInvalidated) {
   String state = obs.state();
   String current = exec.status();
   return switch (state) {
      case "paused" -> "paused";
      case "unknown" -> "unknown";
      case "stopped" -> "stopped";
      case "running" -> {
         if ("admitted".equals(current) || "running".equals(current)) yield "running";
         if ("paused".equals(current)
             && !newInvalidated
             && (obs.continuityValid() == null || obs.continuityValid())
             && (obs.verificationRevision() == null
