Implementation:
```java
public Object full(String raw) { return filter(raw, FULL_FIELDS); }
private JsonNode filter(String raw, Map<String, FieldType> whitelist) {
    JsonNode node = readObject(raw);
    if (node == null) return null;
    ObjectNode out = objectMapper.createObjectNode();
    List<String> dropped = new ArrayList<>();
    node.fieldNames().forEachRemaining(name -> {
        if (!whitelist.containsKey(name)) { dropped.add(name); return; }
        JsonNode v = node.get(name);
        if (typeMatches(v, whitelist.get(name))) out.set(name, v);
        else dropped.add(name); // type mismatch -> drop
    });
    if (!dropped.isEmpty()) log.warn("care plan projection dropped non-whitelisted keys: {}", dropped);
    return out.size() == 0 ? null : out;
}
```
