        // 目标成员确实传入 1:1 端口（绑定证据）
        assertEquals(ctx.memberId(), faceDouble.lastRequestedMemberId());
        // media 行存在（人脸已受理）但未挂执行
        var media = jdbc.queryForMap("SELECT state, execution_id FROM media_objects"
