private JsonNode project(String raw, Map<String,Kind> whitelist) {
    return projectObject(readObject(raw), whitelist, "");
}

private JsonNode projectObject(JsonNode source, Map<String,Kind> whitelist, String path) {
    if (source == null || !source.isObject() || source.size()==0) return null;
    ObjectNode out = createObjectNode();
    List<String> dropped = new ArrayList<>();
    source.fieldNames().forEachRemaining(name -> {
        Kind kind = whitelist.get(name);
        String p = path.isEmpty()? name : path + "." + name;
        if (kind == null) { dropped.add(p); return; }
        JsonNode filtered = projectValue(source.get(name), kind, p, dropped);
        if (filtered != null) out.set(name, filtered);
    });
    warn(dropped);
    return out.size()==0 ? null : out;
}

private JsonNode projectValue(JsonNode value, Kind kind, String path, List<String> dropped) {
    if (value == null || value.isNull()) { dropped.add(path); return null; }
    return switch (kind) {
        case STRING -> value.isTextual() ? value : dropAndNull(dropped,path);
        case STEPS -> projectSteps(value, path, dropped);
        case REGIONS -> projectRegions(value, path, dropped);
        case PARAMETERS -> projectParameters(value, path, dropped);
    };
}
